        泰语: '!!! โปรดเลือกเฟิร์มแวร์ที่ตรงกับรุ่นอุปกรณ์ของคุณให้ถูกต้อง (สามารถดูรุ่นอุปกรณ์ได้ในคำสั่งซื้อ Taobao หรือกล่องบรรจุภัณฑ์) หากการอัพเกรดเฟิร์มแวร์ไม่ถูกต้อง คุณต้องติดต่อฝ่ายบริการลูกค้าเพื่อทำการซ่อมแซมจากโรงงาน หากเป็นเหตุให้โรงงานซ่อมต้องรับผลที่ตามมา',
        中文繁体: '！！！請正確選擇與您的設備對應的型號固件（設備型號可在淘寶訂單或者包裝盒上查看），若固件升級錯誤，需要聯繫客服進行返廠維修，如果造成返廠維修後果自行承擔',
