        日语: 'アップグレード中は、いかなる状況でもデバイスのUSBを抜いたり触れたりしないでください。デバイスのプラグを抜いたり触れたりすると、デバイスがフリーズする場合があります。',
        法语: 'Ne débranchez ou ne touchez en aucun cas le dispositif USB pendant le processus de mise à niveau. Si vous débranchez ou touchez l\'appareil, vous risquez d\'endommager votre appareil.',
